if(!$err){$q=db()->prepare('SELECT * FROM users WHERE email=?');$q->execute([$em]);$u=$q->fetch();if($u&&password_verify($_POST['pass'],$u['pass'])){session_regenerate_id(true);$_SESSION['u']=$u;header('Location: dashboard.php');exit;}$err=$err?:'Wrong email or password.';}}
